  + POP(2, '<div class="bigemo">🎬</div><b class="ct">' + TX('תזרים של שנה שלמה') + '</b><p class="lg">' + TX('כמה מזומן הפעילות העסקית עצמה הכניסה לחברה במהלך השנה. את זה מראה הדוח על תזרימי המזומנים.') + '</p>', 'card filmc')
