                   ('הפחת: גידול בלקוחות', PAREN('40'), 'מכירות שנרשמו כהכנסה, והמזומן עוד לא נגבה.', False),
                   ('הפחת: גידול במלאי', PAREN('90'), 'מזומן ששולם על סחורה שעוד לא נמכרה.', False),
                   ('הוסף: גידול בספקים', '40', 'קניות שנרשמו, והמזומן עוד לא שולם.', False),
