   traps={'B8': [('=B4-B3/B5', 'חסרים סוגריים: Excel מחלק קודם את המלאי. כתבו =(B4-B3)/B5.'), ('=B4/B5', 'זה היחס השוטף. ביחס המהיר מורידים את המלאי מהמונה.')], 'B11': [('=B6/B4', 'המכנה הוא ההתחייבויות השוטפות: =B6/B5.')]},
